import pandas as pd


def solve(data):
    ban = pd.read_csv('coffee-sales-cc0.csv')
    cua_mon = ban[ban['coffee_name'] == data['mon']]
    so_luot = int((cua_mon['cash_type'] == data['kieu']).sum())
    tong = int(len(cua_mon))
    return {'so_luot': so_luot, 'tong': tong,
            'ti_le': round(100 * so_luot / tong, 1)}
